import React from "react";
import {
  Dialog,
  DialogContent,
  DialogTitle,
  DialogActions,
  TextField,
  Button,
} from "@mui/material";
import { ThemeProvider } from "@mui/material/styles";
import { theme } from "../../theme";

function AddTaskDialog({
  open,
  onClose,
  text,
  setText,
  description,
  setDescription,
  priority,
  setPriority,
  onAdd,
}) {
  return (
    <Dialog open={open} onClose={onClose} fullWidth>
      <DialogTitle>Descreva sua tarefa</DialogTitle>
      <DialogContent sx={{}}>
        <TextField
          fullWidth
          label="Título da Tarefa"
          value={text}
          onChange={(e) => setText(e.target.value)}
          sx={{ mt: 2 }}
        />

        <TextField
          fullWidth
          multiline
          rows={3}
          label="Descrição"
          value={description}
          onChange={(e) => setDescription(e.target.value)}
          sx={{ mt: 2 }}
        />

        <TextField
          select
          fullWidth
          label="Prioridade"
          value={priority}
          onChange={(e) => setPriority(e.target.value)}
          SelectProps={{ native: true }}
          sx={{ mt: 2 }}
        >
          <option value="Normal">Normal</option>
          <option value="Urgente">Urgente</option>
          <option value="Imediato">Imediato</option>
        </TextField>
      </DialogContent>
      <DialogActions>
        <Button
          onClick={onClose}
          sx={{
            bgcolor: "red",
            color: "#f1f1f1",
          }}
        >
          Cancelar
        </Button>
        <Button
          onClick={() => {
            onAdd();
            onClose();
          }}
          variant="contained"
        >
          Adicionar
        </Button>
      </DialogActions>
    </Dialog>
  );
}

export default AddTaskDialog;
